        if num <= 1:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        max_divisor = math.isqrt(num)
        for d in range(3, max_divisor + 1, 2):
            if num % d == 0:
                return False
        return True

    if is_prime(n):
        return x
